import csv
import json
import sys
from pathlib import Path
from datetime import datetime


def _parse_timestamp(ts: str) -> datetime:
    """Parse an ISO‑8601 timestamp with timezone.
    datetime.fromisoformat handles most ISO formats, including the
    trailing Z (as +00:00) by replacing it.
    """
    # Handle the Z suffix for UTC
    if ts.endswith('Z'):
        ts = ts[:-1] + '+00:00'
    return datetime.fromisoformat(ts)


def reconcile(csv_path: Path) -> dict[str, float | int]:
    # Deduplicate by tx_id, keeping the row with the latest timestamp.
    latest_by_id: dict[str, dict[str, str]] = {}
    latest_ts_by_id: dict[str, datetime] = {}

    with csv_path.open("r", encoding="utf-8", newline="") as f:
        reader = csv.DictReader(f)
        for row in reader:
            tx_id = row["tx_id"]
            ts = _parse_timestamp(row["timestamp"]).replace(tzinfo=None)  # naive UTC for comparison
            # Replace if we have no entry yet, or the new timestamp is newer,
            # or equal (to keep the later row in the file).
            if (tx_id not in latest_by_id) or (ts >= latest_ts_by_id[tx_id]):
                latest_by_id[tx_id] = row
                latest_ts_by_id[tx_id] = ts

    total_valid_amount = 0.0
    valid_count = 0
    failed_count = 0

    for row in latest_by_id.values():
        status = row["status"].strip().upper()
        if status == "VALID":
            valid_count += 1
            try:
                total_valid_amount += float(row["amount"])  # amounts are well‑formed
            except ValueError:
                # If amount is malformed, treat as 0 (should not happen per spec)
                pass
        elif status == "FAILED":
            failed_count += 1
        # All other statuses are ignored

    return {
        "total_valid_amount": round(total_valid_amount, 2),
        "valid_count": valid_count,
        "failed_count": failed_count,
    }


def main() -> None:
    if len(sys.argv) != 2:
        print("Usage: python3 /app/reconcile.py <input_csv>", file=sys.stderr)
        sys.exit(1)
    csv_path = Path(sys.argv[1])
    if not csv_path.is_file():
        print(f"File not found: {csv_path}", file=sys.stderr)
        sys.exit(1)

    summary = reconcile(csv_path)
    print(json.dumps(summary))


if __name__ == "__main__":
    main()
PY
